"""Class to model objects and operations for the ID window in the Mosaiq application"""

from interops.libraries.squish_actions import CommonActions
from interops.libraries.mosaiq.interactions.objects.mosaiq_directory_id_objects import DirectoryIDObjects
from interops.libraries.common.state import get_value, State

class DirectoryID():
    """
    Class used to model a directory ID window and its operations.
    """
    def __init__(self, window_obj=None) -> None:
        '''
        window_obj is used to distiguish different ID window (Staff, Location, etc)
        '''
        if window_obj is not None:
            CommonActions.wait_for_object_exists(window_obj)
        self.identification = State(DirectoryIDObjects.identification_Edit, "")
        self.facility =  State(DirectoryIDObjects.status_Pane, "")
        self.ledger = State(DirectoryIDObjects.ledger_Pane, "")

    @property
    def type(self):
        self._type = get_value(DirectoryIDObjects.type_Pane)
        return self._type
    @type.setter
    def type(self, value: str):
        CommonActions.select_item_in_list_with_acknowledge(DirectoryIDObjects.type_Pane, value)
        self._type = value

    @property
    def department(self):
        self._department = get_value(DirectoryIDObjects.department_Pane)
        return self._department
    @department.setter
    def department(self, value: str):
        CommonActions.select_item_in_list_with_acknowledge(DirectoryIDObjects.department_Pane, value)
        self._department = value

    def click_button(self, btn:str):
        buttons =  {
            "OK":DirectoryIDObjects.oK_Button,
            "Canel":DirectoryIDObjects.cancel_Button,
            "Facilities": DirectoryIDObjects.facility_Button
        }
        if btn in buttons:
            CommonActions.left_click_object(buttons[btn])